                source
            )

        after = retry_results.get(index)
        if after is not None:
            after_status = after.status
            after_stage = after.stage
            after_code = after.code
            after_message = after.message
        else:
            # 复核任务自身失败、该项尚无结果：沿用复核任务的错误定位；
